/* Real PDF integration; case.files remains a page queue for backwards compatibility. */
let pdfWorker=null,pdfSequence=0,pdfBusy=false,pdfImportFiles=[],pdfPreviewToken=0,pdfPreviewReady='',pdfWorkReady='',pdfWorkPage=0,pdfDrawMode=false;
const pdfRequests=new Map(),pdfImages=new Map();
let pdfWorkerReady=false,pdfWorkerTimer;
function pdfStopWorker(error=Error('PDF 處理已取消')){
 clearTimeout(pdfWorkerTimer);pdfWorker?.terminate();pdfWorker=null;pdfWorkerReady=false;
 for(const r of [...pdfRequests.values()])r.reject(error);pdfRequests.clear();
}
function pdfCall(method,args={},signal){return new Promise((resolve,reject)=>{
 if(signal?.aborted)return reject(new DOMException('已取消','AbortError'));
 const id=++pdfSequence;let timer;
 const finish=(fn,value)=>{clearTimeout(timer);signal?.removeEventListener('abort',abort);pdfRequests.delete(id);fn(value);};
 const abort=()=>pdfStopWorker(new DOMException('已取消','AbortError'));
 const request={resolve:v=>finish(resolve,v),reject:e=>finish(reject,e),send:()=>{
  timer=setTimeout(()=>pdfStopWorker(Error('PDF 處理逾時，請重試或將大型檔案分批匯入。')),120000);
  try{pdfWorker.postMessage({id,method,...args});}catch(e){request.reject(e);}
 }};
 pdfRequests.set(id,request);signal?.addEventListener('abort',abort,{once:true});
 if(!pdfWorker){
  try{
   const worker=pdfWorker=new Worker('pdf-worker.js',{type:'module'});
   pdfWorkerTimer=setTimeout(()=>pdfStopWorker(Error('PDF 引擎載入逾時，請檢查連線後重試。')),60000);
   worker.onmessage=({data})=>{
    if(worker!==pdfWorker)return;
    if(data.type==='ready'){clearTimeout(pdfWorkerTimer);pdfWorkerReady=true;for(const r of pdfRequests.values())r.send();return;}
    if(data.type==='init-error'){pdfStopWorker(Error('PDF 引擎載入失敗：'+data.error));return;}
    const r=pdfRequests.get(data.id);if(r)data.error?r.reject(Error(data.error)):r.resolve(data.result);
   };
   worker.onerror=worker.onmessageerror=()=>{if(worker===pdfWorker)pdfStopWorker(Error('PDF 引擎載入或通訊失敗，請重試。'));};
  }catch(e){pdfStopWorker(Error('無法啟動 PDF 引擎：'+e.message));}
 }else if(pdfWorkerReady)request.send();
});}
function pdfWait(promise,signal,timeout=30000){return new Promise((resolve,reject)=>{
 let timer;const done=(fn,v)=>{clearTimeout(timer);signal?.removeEventListener('abort',abort);fn(v);};
 const abort=()=>done(reject,new DOMException('已取消','AbortError'));
 if(signal?.aborted)return abort();signal?.addEventListener('abort',abort,{once:true});
 timer=setTimeout(()=>done(reject,Error('讀取或儲存逾時，請重試。')),timeout);
 Promise.resolve(promise).then(v=>done(resolve,v),e=>done(reject,e));
});}
let pdfDBPromise;
function pdfDB(){return pdfDBPromise??=new Promise((resolve,reject)=>{
 const request=indexedDB.open('drawing-desk-pdf',1);let settled=false;
 const fail=()=>{if(settled)return;settled=true;clearTimeout(timer);pdfDBPromise=null;reject(Error('無法開啟本機儲存空間，請關閉其他分頁後重試。'));};
 const timer=setTimeout(fail,15000);
 request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('sources'))request.result.createObjectStore('sources');};
 request.onsuccess=()=>{if(settled){request.result.close();return;}settled=true;clearTimeout(timer);const db=request.result;db.onversionchange=()=>{db.close();pdfDBPromise=null;};resolve(db);};
 request.onerror=request.onblocked=fail;
});}
async function pdfStore(action,key,value,signal){const db=await pdfWait(pdfDB(),signal);return new Promise((resolve,reject)=>{
 if(signal?.aborted)return reject(new DOMException('已取消','AbortError'));
 const tx=db.transaction('sources',action==='get'?'readonly':'readwrite'),s=tx.objectStore('sources'),r=action==='put'?s.put(value,key):action==='delete'?s.delete(key):s.get(key);let result;
 const abort=()=>{try{tx.abort();}catch{}};
 const timer=setTimeout(abort,30000);signal?.addEventListener('abort',abort,{once:true});
 const finish=(fn,v)=>{clearTimeout(timer);signal?.removeEventListener('abort',abort);fn(v);};
 r.onsuccess=()=>result=r.result;tx.oncomplete=()=>finish(resolve,result);
 tx.onabort=tx.onerror=()=>finish(reject,signal?.aborted?new DOMException('已取消','AbortError'):Error('本機儲存失敗或逾時，請確認可用空間後重試。'));
});}
async function pdfBytes(f){const blob=await pdfStore('get',f.sourceId);if(!blob)throw Error('找不到原始 PDF。請重新匯入；此瀏覽器的檔案可能已被清除。');return blob.arrayBuffer();}
function pdfGroups(c=current()){const groups=new Map();for(const f of c.files){const key=f.sourceId||f.id||(f.id=crypto.randomUUID());if(!groups.has(key))groups.set(key,{id:key,name:f.name,real:!!f.sourceId,pages:[]});groups.get(key).pages.push(f);}for(const g of groups.values())g.pages.sort((a,b)=>(a.pageIndex||0)-(b.pageIndex||0));return [...groups.values()];}
function pdfLabel(f){return f.sourceId?`${f.name} · 第 ${f.pageIndex+1} / ${f.pageCount} 頁`:f.name;}
function pdfRuleMasks(rule){return rule==='A'?[{x:62,y:81,w:34,h:6,color:'#000000',label:'規則候選：右下圖框'}]:rule==='B'?[{x:4,y:4,w:30,h:10,color:'#000000',label:'規則候選：左上標誌'}]:[];}
function pdfNoteRuns(note){const doc=new DOMParser().parseFromString(noteMarkup(note),'text/html'),runs=[];const add=(text,bold=false,underline=false)=>{if(text)runs.push({text,bold,underline});};function walk(n,b=false,u=false){if(n.nodeType===3){add(n.textContent,b,u);return;}if(n.nodeType!==1)return;const tag=n.tagName.toLowerCase();if(tag==='br'){add('\n');return;}if(['div','p','ol','ul'].includes(tag)&&runs.length&&!runs.at(-1).text.endsWith('\n'))add('\n');if(tag==='li'){const parent=n.parentElement;add(parent.tagName==='OL'?`${[...parent.children].indexOf(n)+1}. `:'• ',b);}for(const child of n.childNodes)walk(child,b||tag==='b'||tag==='strong',u||tag==='u');if(['li','p','div'].includes(tag))add('\n');}for(const n of doc.body.childNodes)walk(n);while(runs.length&&/^\n+$/.test(runs.at(-1).text))runs.pop();return runs;}
function pdfPageData(f){return {pageIndex:f.pageIndex,rotation:f.rotation||0,revision:f.revision||0,masks:structuredClone(f.masks||[]),notes:(f.notes||[]).map(n=>({...n,fontSize:n.fontSize||10,textColor:textColor(n.color),runs:pdfNoteRuns(n)}))};}
function pdfKey(f){return `${f.sourceId}:${f.pageIndex}:${f.revision||0}:${JSON.stringify([f.masks,f.notes])}`;}
let pdfActiveTask=null;
function pdfCancelProgress(d){
 if(d.finished){d.close();return;}d.cancelRequested=true;d.controller.abort();
 if(pdfActiveTask===d){pdfBusy=false;pdfActiveTask=null;}
 d.close();notify('已取消本次處理，既有案件內容保留。');
}
function pdfProgress(title){const d=caseDialog('pdfProgressDialog',`<div class="pdf-progress-heading"><h2 id="pdfProgressDialogTitle">${title}</h2><button type="button" aria-label="取消處理並關閉" title="取消處理並關閉" onclick="pdfCancelProgress(this.closest('dialog'))">${uiIcon('clear')}</button></div><p id="pdfProgressText" role="status">準備中…</p><progress id="pdfProgressBar" value="0" max="100"></progress><div id="pdfProgressDetails"></div><div class="actions"><button type="button" id="pdfCancelBatch" onclick="pdfCancelProgress(this.closest('dialog'))">取消本次處理</button><button type="button" id="pdfProgressClose" hidden onclick="this.closest('dialog').close()">關閉</button></div>`);
 d.controller=new AbortController();pdfActiveTask=d;
 d.oncancel=e=>{e.preventDefault();pdfCancelProgress(d);};
 d.addEventListener('close',()=>{if(!d.finished&&!d.cancelRequested){d.cancelRequested=true;d.controller.abort();if(pdfActiveTask===d){pdfActiveTask=null;pdfBusy=false;}}});return d;
}
function pdfProgressUpdate(text,value){const t=$('#pdfProgressText'),p=$('#pdfProgressBar');if(t)t.textContent=text;if(p)p.value=value;}
async function pdfImport(selected,rule){
 const records=[],stored=[],errors=[];pdfBusy=true;const d=pdfProgress('匯入 PDF'),signal=d.controller.signal;
 try{for(let i=0;i<selected.length;i++){
  if(signal.aborted)break;const source=selected[i];
  try{
   if(!/\.pdf$/i.test(source.name))throw Error('僅支援 PDF 檔案');
   pdfProgressUpdate(`讀取 ${i+1} / ${selected.length}：${source.name}`,i/selected.length*100);
   const buffer=await pdfWait(source.arrayBuffer(),signal);
   pdfProgressUpdate(`解析 ${source.name}${pdfWorkerReady?'':' · 首次載入 PDF 引擎，請稍候'}`,i/selected.length*100);
   const pages=await pdfCall('inspect',{bytes:buffer},signal);
   if(!pages.length)throw Error('PDF 沒有可用頁面');
   const sourceId=crypto.randomUUID();stored.push(sourceId);
   await pdfStore('put',sourceId,new Blob([buffer],{type:'application/pdf'}),signal);
   if(signal.aborted)break;
   records.push(...pages.map((p,pageIndex)=>({id:crypto.randomUUID(),sourceId,name:source.name,pageIndex,pageCount:pages.length,width:p.width,height:p.height,rule,status:'待確認',accepted:false,masks:pdfRuleMasks(rule),notes:[],history:[],revision:0})));
  }catch(e){if(signal.aborted)break;errors.push(`${source.name}：${e.message}`);}
 }
 if(signal.aborted){for(const id of stored)pdfStore('delete',id).catch(()=>{});return {records:[],stored:[],errors:[],cancelled:true};}
 return {records,stored:stored.filter(id=>records.some(r=>r.sourceId===id)),errors,cancelled:false};
 }finally{d.finished=true;if(pdfActiveTask===d){pdfBusy=false;pdfActiveTask=null;}if(d.open)d.close();}
}
function pdfImportReport(result){if(!result.cancelled&&result.errors.length)caseDialog('pdfImportReport',`<h2 id="pdfImportReportTitle">匯入結果</h2><p>已加入 ${result.stored.length} 份檔案、${result.records.length} 頁。${result.cancelled?'後續匯入已停止。':''}</p><ul>${result.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><p>失敗的檔案未加入案件，修正後可重新匯入。</p><button onclick="this.closest('dialog').close()">關閉</button>`);}
let pdfUploadFeedback={wizard:'',dialog:''};
function pdfUploadIcon(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M12 18v-7m-3 3 3-3 3 3"/></svg>';}
function pdfUploadZone(context){const id=context==='wizard'?'wizardPdfInput':'caseImportFiles';return `<div class="pdf-upload-zone ${pdfUploadRows(context).length?'is-compact':''}" data-upload-context="${context}" ondragenter="pdfUploadDrag(event,true)" ondragover="pdfUploadOver(event)" ondragleave="pdfUploadDrag(event,false)" ondrop="pdfUploadDrop(event,'${context}')"><div class="pdf-upload-symbol">${pdfUploadIcon()}</div><h2>將 PDF 圖面拖曳至此</h2><p class="pdf-upload-touch">選取裝置中的 PDF 圖面</p><p class="pdf-upload-caption">支援多份檔案與多頁 PDF</p><button type="button" class="primary pdf-upload-choose" onclick="document.getElementById('${id}').click()">${uiIcon('original')}選擇 PDF 檔案</button><input id="${id}" class="pdf-upload-input" type="file" accept="application/pdf,.pdf" multiple aria-label="選擇 PDF 檔案" tabindex="-1" onchange="pdfUploadAdd(this.files,'${context}');this.value='' "><p class="pdf-upload-private"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>檔案僅在此裝置處理與保存</p></div><p class="pdf-upload-feedback" id="pdfUploadFeedback-${context}" role="status" aria-live="polite">${esc(pdfUploadFeedback[context])}</p><div id="pdfUploadList-${context}">${pdfUploadList(context)}</div>`;}
function pdfUploadGet(context){return context==='wizard'?pdfImportFiles:(document.querySelector('#caseImportDialog')?.pdfFiles||[]);}
function pdfUploadSize(n){return n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.ceil(n/1024))+' KB';}
const uploadListState={wizard:{query:'',page:0},dialog:{query:'',page:0}};
function pdfUploadRows(context){const files=pdfUploadGet(context);return (files.length?files:context==='wizard'?pendingNames.map(name=>({name})):[]).map((f,i)=>({f,i}));}
function pdfUploadList(context){const rows=pdfUploadRows(context);if(!rows.length)return '';const state=uploadListState[context],files=pdfUploadGet(context);return `<div class="pdf-upload-list"><div class="pdf-upload-list-heading"><strong>已選擇 ${rows.length} 份${files.length?'檔案':'示範圖面'}</strong><span>${files.length?pdfUploadSize(files.reduce((n,f)=>n+f.size,0)):'示範'}</span></div><input class="upload-list-search" type="search" aria-label="搜尋已選檔案" placeholder="搜尋已選檔名" value="${esc(state.query)}" oninput="uploadListState['${context}'].query=this.value;uploadListState['${context}'].page=0;pdfUploadResultsRefresh('${context}')"><div id="uploadResults-${context}">${pdfUploadResults(context)}</div></div>`;}
function pdfUploadResults(context){const state=uploadListState[context],rows=pdfUploadRows(context).filter(({f})=>f.name.toLocaleLowerCase().includes(state.query.trim().toLocaleLowerCase())),pages=Math.max(1,Math.ceil(rows.length/10));state.page=Math.max(0,Math.min(state.page,pages-1));const start=state.page*10;return `<p class="upload-result-count" role="status">${rows.length?'顯示 '+(start+1)+'–'+Math.min(start+10,rows.length)+' / '+rows.length+' 份':'沒有符合的檔案'} · 每頁 10 份</p><ul>${rows.slice(start,start+10).map(({f,i})=>`<li><span class="pdf-upload-file-icon">${uiIcon('original')}</span><div class="pdf-upload-file-text"><strong>${esc(f.name)}</strong><small>${f.size!==undefined?pdfUploadSize(f.size):'示範圖面'}</small></div><button class="pdf-upload-remove" type="button" title="移除此檔案" aria-label="移除 ${esc(f.name)}" onclick="pdfUploadRemove('${context}',${i})">${uiIcon('clear')}</button></li>`).join('')}</ul><div class="upload-list-pagination"><button type="button" ${state.page?'':'disabled'} onclick="uploadListState['${context}'].page--;pdfUploadResultsRefresh('${context}')">上一頁</button><span>${state.page+1} / ${pages}</span><button type="button" ${state.page+1<pages?'':'disabled'} onclick="uploadListState['${context}'].page++;pdfUploadResultsRefresh('${context}')">下一頁</button></div>`;}
function pdfUploadResultsRefresh(context){const el=document.querySelector('#uploadResults-'+context);if(el){el.innerHTML=pdfUploadResults(context);const list=el.querySelector('ul');if(list)list.scrollTop=0;}}
function pdfUploadRefresh(context){document.querySelector(`[data-upload-context="${context}"]`)?.classList.toggle('is-compact',pdfUploadRows(context).length>0);if(context==='wizard'){pendingNames=pdfImportFiles.length?pdfImportFiles.map(f=>f.name):pendingNames;render();}else{const list=$('#pdfUploadList-dialog');if(list)list.innerHTML=pdfUploadList(context);const feedback=$('#pdfUploadFeedback-dialog');if(feedback)feedback.textContent=pdfUploadFeedback.dialog;const button=$('#caseImportSubmit');if(button)button.disabled=!pdfUploadGet('dialog').length;}}
function pdfUploadAdd(input,context){const added=[...input],files=[...pdfUploadGet(context)],seen=new Set(files.map(f=>[f.name,f.size,f.lastModified].join('|')));let invalid=0,duplicates=0,accepted=0;for(const f of added){if(!/\.pdf$/i.test(f.name)){invalid++;continue;}const key=[f.name,f.size,f.lastModified].join('|');if(seen.has(key)){duplicates++;continue;}seen.add(key);files.push(f);accepted++;}if(context==='wizard'){pdfImportFiles=files;if(files.length)pendingNames=files.map(f=>f.name);}else{const dialog=$('#caseImportDialog');if(!dialog)return;dialog.pdfFiles=files;}pdfUploadFeedback[context]=[accepted?`已加入 ${accepted} 份 PDF。`:'',invalid?`${invalid} 份非 PDF 檔案已略過。`:'',duplicates?`${duplicates} 份重複檔案已略過。`:''].filter(Boolean).join(' ');pdfUploadRefresh(context);}
function pdfUploadRemove(context,i){if(context==='wizard'){if(pdfImportFiles.length){pdfImportFiles.splice(i,1);pendingNames=pdfImportFiles.map(f=>f.name);}else pendingNames.splice(i,1);}else pdfUploadGet(context).splice(i,1);pdfUploadFeedback[context]='已移除選取的檔案。';pdfUploadRefresh(context);}
function pdfUploadOver(e){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='copy';}
function pdfUploadDrag(e,enter){e.preventDefault();const zone=e.currentTarget;zone.dataset.dragDepth=Math.max(0,Number(zone.dataset.dragDepth||0)+(enter?1:-1));zone.classList.toggle('is-dragging',Number(zone.dataset.dragDepth)>0);}
function pdfUploadDrop(e,context){e.preventDefault();e.stopPropagation();e.currentTarget.dataset.dragDepth=0;e.currentTarget.classList.remove('is-dragging');pdfUploadAdd(e.dataTransfer?.files||[],context);}
function pdfUploadDemo(){pdfImportFiles=[];pendingNames=['BRACKET-DEMO.pdf','HOUSING-DEMO.pdf','PLATE-DEMO.pdf'];pdfUploadFeedback.wizard='已加入 3 份示範圖面。';render();}
pickFiles=function(fs){pdfUploadAdd(fs,'wizard');};
// Prevent dropping a file outside the target from replacing the current page.
for(const type of ['dragover','drop'])document.addEventListener(type,e=>{if((route==='import'||document.querySelector('#caseImportDialog[open]'))&&Array.from(e.dataTransfer?.types||[]).includes('Files'))e.preventDefault();});

const uploadCreateCase=createCase;createCase=function(e){if(!wizardDraft&&route!=='edit-case'){pdfImportFiles=[];uploadListState.wizard={query:'',page:0};pdfUploadFeedback.wizard='';}return uploadCreateCase(e);};
const oldCancelWizard=cancelCaseWizard;cancelCaseWizard=function(){pdfImportFiles=[];oldCancelWizard();};
importPage=function(){return title('匯入圖面',esc(current().name),'')+wizardSteps(2)+`<section class="card pdf-import-card">${pdfUploadZone('wizard')}<div class="pdf-upload-demo"><span>尚未準備圖面？</span><button type="button" class="textbtn" onclick="pdfUploadDemo()">使用示範圖面</button></div><div class="footerbar pdf-upload-footer">${btn('上一步：案件資訊',"go(wizardDraft && cases.some(c=>c.id===wizardDraft.id) ? 'edit-case' : 'new')")}<button class="primary" ${pendingNames.length?'':'disabled'} onclick="go('setup')">下一步：選擇規則</button></div></section>`;};
const oldStartJobs=startJobs;startJobs=async function(){if(pdfBusy)return;if(!pdfImportFiles.length){oldStartJobs();return;}const rule=$('#rule').value,c=structuredClone(current()),result=await pdfImport(pdfImportFiles,rule);if(result.cancelled)return;if(!result.records.length){pdfImportReport(result);notify('沒有可加入的圖面，請重新選擇 PDF。');return;}c.files.push(...result.records);c.rule=rule;c.pendingNames=[];c.savedAt=new Date().toISOString();c.resumeRoute='case';const next=cases.some(x=>x.id===c.id)?cases.map(x=>x.id===c.id?c:x):[c,...cases];if(!writeCaseStore(next,logs)){await Promise.all(result.stored.map(id=>pdfStore('delete',id)));return;}cases=next;cid=c.id;wizardDraft=null;pendingNames=[];pdfImportFiles=[];fi=0;go('case');pdfImportReport(result);notify(`已儲存 ${result.stored.length} 份 PDF、${result.records.length} 頁；規則已逐頁套用。`);};
openCaseImport=function(){uploadListState.dialog={query:'',page:0};pdfUploadFeedback.dialog='';const d=caseDialog('caseImportDialog',`<form onsubmit="submitCaseImport(event)"><h2 id="caseImportDialogTitle">匯入 PDF 圖面</h2><p>新增圖面至目前案件，既有內容會保留。</p>${pdfUploadZone('dialog')}<label class="field">套用至本次匯入的每一頁<select id="caseImportRule"><option value="manual">人工圈選 · 不預設遮蔽</option><option value="A">客戶 A · 右下圖框 v1.2</option><option value="B">客戶 B · 左上標誌 v1.0</option></select></label><p class="review-important">規則為相對位置候選區；不同頁面版型仍須逐頁核對。</p><div class="actions"><button type="button" onclick="this.closest('dialog').close()">取消</button><button id="caseImportSubmit" class="primary" disabled>匯入全部頁面</button></div></form>`);d.dataset.caseId=current().id;d.pdfFiles=[];$('#caseImportRule').value=current().rule||'manual';};
submitCaseImport=async function(e){e.preventDefault();if(pdfBusy)return;const d=$('#caseImportDialog'),target=cases.find(c=>c.id===d.dataset.caseId),selected=[...(d.pdfFiles||[])],rule=$('#caseImportRule').value;if(!selected.length||!target)return;d.close();const result=await pdfImport(selected,rule);if(result.cancelled)return;if(result.records.length){const next=cases.map(c=>c.id===target.id?{...c,files:[...c.files,...result.records],savedAt:new Date().toISOString()}:c);if(writeCaseStore(next,logs)){cases=next;render();notify(`已加入 ${result.stored.length} 份 PDF、${result.records.length} 頁`);}else await Promise.all(result.stored.map(id=>pdfStore('delete',id)));}pdfImportReport(result);};
const originalSetup=setupPage;setupPage=function(){return originalSetup().replace('仍需人工逐檔確認','將套用至每一頁，仍需人工逐頁確認');};
const originalDrawing=drawing;drawing=function(){return file()?.sourceId?'<canvas class="pdf-canvas" aria-label="PDF 圖面"></canvas><span class="pdf-render-message" role="status">載入原始圖面…</span>':originalDrawing();};
const originalAcceptMask=acceptMask;acceptMask=function(){if(file()?.sourceId&&pdfWorkReady!==file().sourceId+':'+file().pageIndex)return notify('請等待圖面載入完成後再確認');originalAcceptMask();};
const originalDirty=dirty;dirty=function(){originalDirty();const f=file();f.revision=(f.revision||0)+1;f.checks=[false,false,false];pdfPreviewReady='';};
const originalClear=clearObjects;clearObjects=function(type,reset=false){if(!file().sourceId||type!=='mask'||!reset)return originalClear(type,reset);if(!confirm('依此頁的客戶規則恢復候選區？可使用復原還原。'))return;snapshot();file().masks=pdfRuleMasks(file().rule||'manual');selection=null;render();};
function pdfSelectPage(index){selection=null;pdfDrawMode=false;openFile(index);}
function pdfPageNavigation(f){if(!f.sourceId)return '';const group=pdfGroups().find(g=>g.id===f.sourceId),pos=group.pages.indexOf(f);return `<div class="pdf-page-nav"><strong>第 ${f.pageIndex+1} / ${f.pageCount} 頁</strong><span>${Math.round(f.width*25.4/72)} × ${Math.round(f.height*25.4/72)} mm</span><button ${pos?'':'disabled'} onclick="pdfSelectPage(${current().files.indexOf(group.pages[pos-1])})">上一頁</button><label>跳至第 <input aria-label="跳至頁碼" type="number" min="1" max="${f.pageCount}" value="${f.pageIndex+1}" onchange="pdfJumpPage(this.value)"> 頁</label><button ${pos<group.pages.length-1?'':'disabled'} onclick="pdfSelectPage(${current().files.indexOf(group.pages[pos+1])})">下一頁</button></div>`;}
function pdfJumpPage(n){const f=file(),target=current().files.findIndex(p=>p.sourceId===f.sourceId&&p.pageIndex===Number(n)-1);if(target>=0)pdfSelectPage(target);else notify('請輸入有效頁碼');}
const originalWork=workPage;workPage=function(){let html=originalWork();if(!file()?.sourceId)return html;html=html.replace(esc(file().name),esc(pdfLabel(file()))).replace('<div class="zoom-toolbar" role="group" aria-label="圖面縮放">','<div class="zoom-toolbar" role="group" aria-label="頁面導覽與圖面縮放">'+pdfPageNavigation(file())).replace('示範圖面，非生產用途。修改後需重新確認。','原始 PDF 保留。每頁修改後需重新確認；最後請檢查實際出圖預覽。').replace('實際 PDF 去識別化仍為模擬。','匯出時移除遮蔽區內的內容。').replace('</div><div class="drawing-stage">',`<button class="${pdfDrawMode?'primary':''}" aria-pressed="${pdfDrawMode}" onclick="pdfDrawMode=!pdfDrawMode;view='處理預覽';render()">${uiIcon('mask')}圈選遮蔽</button></div><div class="drawing-stage">`);return html;};
sizeDrawing=function(){const viewport=$('#drawingViewport'),paper=$('#paper');if(!viewport||!paper)return;const f=file(),ratio=f?.sourceId?f.width/f.height:1.25,width=Math.min(viewport.clientWidth,viewport.clientHeight*ratio)*zoomLevel/100;paper.style.width=width+'px';paper.style.height=width/ratio+'px';if(f?.sourceId)paper.style.setProperty('--pdf-scale',width/f.width);viewport.classList.toggle('can-pan',zoomLevel>100);fitAllNotes();};
const originalFit=fitNote;fitNote=function(el){if(!file()?.sourceId)return originalFit(el);const n=file().notes[+el.dataset.index],paper=$('#paper');if(!n||!paper)return;n.fontSize??=10;el.style.fontSize=(n.fontSize*paper.clientWidth/file().width)+'px';el.style.padding=(4*paper.clientWidth/file().width)+'px';const content=el.querySelector('.object-content');content.style.height='auto';const needed=(content.scrollHeight+12*paper.clientWidth/file().width)/paper.clientHeight*100;n.h=Math.min(100,Math.max(n.h,needed));n.y=Math.max(0,Math.min(n.y,100-n.h));el.style.height=n.h+'%';el.style.top=n.y+'%';content.style.height='100%';};
const originalPan=bindPan;bindPan=function(){originalPan();if(!pdfDrawMode||view==='原圖')return;const viewport=$('#drawingViewport'),paper=$('#paper');viewport.classList.add('draw-mode');viewport.onpointerdown=e=>{if(e.button!==0||e.target.closest('.editobject')||!paper.contains(e.target))return;e.preventDefault();const b=paper.getBoundingClientRect(),start=[(e.clientX-b.left)/b.width*100,(e.clientY-b.top)/b.height*100];const box=document.createElement('div');box.className='pdf-draft-mask';paper.append(box);let end=start;viewport.setPointerCapture(e.pointerId);viewport.onpointermove=ev=>{end=[Math.max(0,Math.min(100,(ev.clientX-b.left)/b.width*100)),Math.max(0,Math.min(100,(ev.clientY-b.top)/b.height*100))];Object.assign(box.style,{left:Math.min(start[0],end[0])+'%',top:Math.min(start[1],end[1])+'%',width:Math.abs(end[0]-start[0])+'%',height:Math.abs(end[1]-start[1])+'%'});};const finish=ev=>{viewport.onpointermove=null;viewport.onpointerup=null;viewport.onpointercancel=null;box.remove();if(ev.type!=='pointercancel'&&Math.abs(end[0]-start[0])>1&&Math.abs(end[1]-start[1])>1){snapshot();file().masks.push({x:Math.min(start[0],end[0]),y:Math.min(start[1],end[1]),w:Math.abs(end[0]-start[0]),h:Math.abs(end[1]-start[1]),color:lastColors.mask,label:'手動遮蔽'});pdfDrawMode=false;pickObject('mask',file().masks.length-1);}else render();};viewport.onpointerup=finish;viewport.onpointercancel=finish;};};
workFileList=function(){const groups=pdfGroups().map(g=>({...g,pages:g.pages.filter(f=>(workStatus==='全部'||workFileStatus(f)===workStatus)&&f.name.toLowerCase().includes(workSearch.toLowerCase()))})).filter(g=>g.pages.length);if(workSort!=='original')groups.sort((a,b)=>a.name.localeCompare(b.name,'zh-TW',{numeric:true})*(workSort==='desc'?-1:1));const pages=Math.max(1,Math.ceil(groups.length/15));pdfWorkPage=Math.min(pdfWorkPage,pages-1);return `<p class="file-result-count">${groups.length} 份檔案 · ${groups.reduce((n,g)=>n+g.pages.length,0)} 頁符合</p>`+groups.slice(pdfWorkPage*15,pdfWorkPage*15+15).map(g=>`<details class="pdf-file-group" ${g.pages.includes(file())?'open':''}><summary><strong>${esc(g.name)}</strong><small>${g.pages.length} 頁${g.real?'':' · 示範'}</small></summary>${g.pages.map(f=>`<button class="${f===file()?'selected':''}" onclick="pdfSelectPage(${current().files.indexOf(f)})"><span>第 ${(f.pageIndex||0)+1} 頁</span>${badge(workFileStatus(f))}</button>`).join('')}</details>`).join('')+`<div class="pdf-list-pager"><button ${pdfWorkPage?'':'disabled'} onclick="pdfWorkPage--;refreshWorkFiles()">上一組</button><small>${pdfWorkPage+1}/${pages}</small><button ${pdfWorkPage+1<pages?'':'disabled'} onclick="pdfWorkPage++;refreshWorkFiles()">下一組</button></div>`;};
const originalOpenFile=openFile;openFile=function(n){const f=current().files[n];if(f?.sourceId){pdfPreviewReady='';pdfWorkReady='';zoomLevel=100;}originalOpenFile(n);};
const originalWorkControls=workListControls;workListControls=function(){return originalWorkControls().replaceAll('refreshWorkFiles()', 'pdfWorkPage=0;refreshWorkFiles()');};
const originalReviewPreview=reviewPreview;reviewPreview=function(f){if(!f.sourceId)return originalReviewPreview(f);return `<div class="review-preview-viewport"><div class="review-paper pdf-review-paper" id="reviewPaper" style="width:${reviewZoom}%;aspect-ratio:${f.width}/${f.height}"><canvas class="pdf-canvas"></canvas><span class="pdf-render-message" role="status">產生實際出圖預覽…</span></div></div><div class="review-preview-tools"><span>第 ${f.pageIndex+1} / ${f.pageCount} 頁 · ${Math.round(f.width*25.4/72)} × ${Math.round(f.height*25.4/72)} mm</span><div><button id="reviewZoomOut" onclick="setReviewZoom(reviewZoom-25)">縮小</button><output id="reviewZoomValue">${reviewZoom}%</output><button id="reviewZoomIn" onclick="setReviewZoom(reviewZoom+25)">放大</button><button onclick="setReviewZoom(100)">適合寬度</button></div></div>`;};
function reviewDocumentGroups(){const matches=new Set(reviewMatches().map(r=>r.f));return pdfGroups().map(g=>({...g,matching:g.pages.filter(f=>matches.has(f))})).filter(g=>g.matching.length);}
function reviewGroupPage(index){return Math.max(0,Math.floor(reviewDocumentGroups().findIndex(g=>g.matching.includes(current().files[index]))/20));}
function reviewPageButton(f,multi){const i=current().files.indexOf(f);return `<button class="review-file ${multi?'review-page-child':''} ${i===fi?'active':''}" aria-current="${i===fi?'true':'false'}" aria-label="${esc(f.name)}，第 ${(f.pageIndex||0)+1} 頁，${reviewStatus(f)}" onclick="selectReviewFile(${i})"><strong>${multi?'第 '+((f.pageIndex||0)+1)+' 頁':esc(f.name)}</strong><span class="review-file-state ${isExportReady(f)?'done':f.status==='處理失敗'?'failed':''}">${reviewStatus(f)}</span></button>`;}
reviewList=function(){const groups=reviewDocumentGroups(),pages=Math.max(1,Math.ceil(groups.length/20));reviewListPage=Math.max(0,Math.min(reviewListPage,pages-1));return `<p class="review-list-count" role="status">${groups.length} 份檔案 · ${groups.reduce((n,g)=>n+g.matching.length,0)} 頁符合</p><div class="review-file-items">${groups.slice(reviewListPage*20,reviewListPage*20+20).map(g=>g.pages.length===1?reviewPageButton(g.matching[0],false):`<section class="review-document-group" aria-label="${esc(g.name)}，共 ${g.pages.length} 頁"><div class="review-document-heading"><strong>${esc(g.name)}</strong><span class="review-document-meta">多頁 PDF · ${g.pages.length} 頁</span><small>已確認 ${g.pages.filter(isExportReady).length} / ${g.pages.length} 頁${g.matching.length<g.pages.length?' · 篩選顯示 '+g.matching.length+' 頁':''}</small></div><div class="review-document-pages">${g.matching.map(f=>reviewPageButton(f,true)).join('')}</div></section>`).join('')||'<p>沒有符合條件的圖面</p>'}</div><div class="review-pagination"><button aria-label="上一頁檔案清單" ${reviewListPage?'':'disabled'} onclick="reviewListPage--;refreshReviewList()">上一頁</button><span>${reviewListPage+1} / ${pages}</span><button aria-label="下一頁檔案清單" ${reviewListPage+1<pages?'':'disabled'} onclick="reviewListPage++;refreshReviewList()">下一頁</button></div>`;};
const originalReviewPage=reviewPage;reviewPage=function(){let html=originalReviewPage();if(file()?.sourceId)html=html.replace('本頁展示人工確認流程。遮蔽與安全檢查尚未實際執行。','請檢查下方實際出圖。遮蔽會移除相交的文字、線條及影像像素，必要尺寸與技術線條也須確認。').replace(esc(file().name)+' · 工作版本 v1',esc(pdfLabel(file())));return html;};
const originalReviewProgress=reviewProgress;reviewProgress=function(){return originalReviewProgress().replace('每張圖面須各自完成三項核對，通過後才會列入匯出項目。','每頁須完成三項核對。同一份 PDF 全部頁面通過後，才會列入匯出項目。');};
const originalSelectReview=selectReviewFile;selectReviewFile=function(i){selection=null;pdfPreviewReady='';reviewListPage=reviewGroupPage(i);originalSelectReview(i);};
const originalReviewZoom=setReviewZoom;setReviewZoom=function(n){originalReviewZoom(n);if(file()?.sourceId)pdfMountPreview();};
const originalSyncApproval=syncReviewApproval;syncReviewApproval=function(){originalSyncApproval();const f=file();if(f?.sourceId&&pdfPreviewReady!==pdfKey(f)){const button=$('#reviewApprove');if(button)button.disabled=true;const hint=$('#reviewApprovalHint');if(hint)hint.textContent='請等待實際出圖預覽完成；若失敗請返回工作台修正。';}};
const originalApprove=approve;approve=function(){const f=file();if(!f?.sourceId)return originalApprove();if(pdfPreviewReady!==pdfKey(f))return notify('請先完成實際出圖預覽');if(!f.accepted||![1,2,3].every(i=>$('#check'+i)?.checked)||isExportReady(f))return;f.status='可匯出';f.approvedRevision=f.revision||0;current().savedAt=new Date().toISOString();logs.push({caseId:cid,file:pdfLabel(f),time:new Date().toLocaleString('zh-TW'),action:'逐頁人工確認通過'});if(!writeCaseStore())markCaseUnsaved();render();notify('本頁已通過；整份 PDF 全部頁面通過後可匯出。');};
exportReadyFiles=function(c){return pdfGroups(c).filter(g=>g.pages.every(isExportReady)).flatMap(g=>g.pages);};
exportSummary=function(c){const groups=pdfGroups(c),ready=groups.filter(g=>g.pages.every(isExportReady));return `<div class="review-count-summary">案件總計 <b>${groups.length} 份 PDF / ${c.files.length} 頁</b><span>可匯出 <b>${ready.length} 份 / ${ready.reduce((n,g)=>n+g.pages.length,0)} 頁</b></span><span>待工作台確認 <b>${c.files.filter(f=>!isExportReady(f)).length} 頁</b></span></div>`;};
reviewExportAction=function(){const ready=pdfGroups().filter(g=>g.pages.every(isExportReady));return `<button class="primary" ${ready.length?'':'disabled'} onclick="go('export')">查看可匯出項目（${ready.length} 份）</button>`;};
const originalCaseExport=caseExportButton;caseExportButton=function(c){const n=pdfGroups(c).filter(g=>g.pages.every(isExportReady)).length;return `<span class="disabled-tip" title="${n?'查看全部頁面已通過的檔案':'需有一份 PDF 的全部頁面通過最終核對'}"><button ${n?'':'disabled'} onclick="go('export')">查看可匯出項目（${n} 份）</button></span>`;};
const originalCasePage=casePage;casePage=function(){let html=originalCasePage();const groups=pdfGroups();html=html.replace(`總計 ${current().files.length} 份圖面`,`總計 ${groups.length} 份檔案 / ${current().files.length} 頁`).replace('原型中的檔案處理、檢核及匯出皆為示範','PDF 原始檔與進度保存在此瀏覽器；AI 處理尚未串接。');const start=html.indexOf('<tbody>'),end=html.indexOf('</tbody>',start);if(start>=0)html=html.slice(0,start+7)+groups.map(g=>{const done=g.pages.filter(isExportReady).length;const index=current().files.indexOf(g.pages.find(f=>!isExportReady(f))||g.pages[0]);return `<tr class="drawing-file-row" tabindex="0" aria-label="開啟圖面 ${esc(g.name)}" onclick="openDrawingRow(event,${index})" onkeydown="openDrawingRow(event,${index})"><td><b>${esc(g.name)}</b><small>${g.real?'原始 PDF':'示範圖面'} · ${g.pages.length} 頁 · ${ruleLabel(g.pages[0].rule||current().rule)}</small></td><td>${badge(done===g.pages.length?'可匯出':'待確認')}</td><td>已通過 ${done} / ${g.pages.length} 頁</td><td><button class="textbtn" onclick="openFile(${current().files.indexOf(g.pages.find(f=>!isExportReady(f))||g.pages[0])})">開啟工作台</button></td></tr>`;}).join('')+html.slice(end);return html;};
function openDrawingRow(event,index){if(event.target.closest('button,a,input,select,textarea,label'))return;if(event.type==='keydown'){if(event.target!==event.currentTarget||!['Enter',' '].includes(event.key))return;event.preventDefault();}openFile(index);}
let pdfExportState=null;
let pdfExportSelection=new Map(),pdfExportAttempt='',pdfExportTimer;
function selectedExportIds(c=current()){const eligible=pdfGroups(c).filter(g=>g.real&&g.pages.every(isExportReady)).map(g=>g.id);const stored=pdfExportSelection.get(c.id);return stored?eligible.filter(id=>stored.includes(id)):eligible;}
function exportSelectionKey(c=current()){const ids=selectedExportIds(c);return c.id+JSON.stringify(pdfGroups(c).filter(g=>ids.includes(g.id)).map(g=>[g.id,g.pages.map(pdfPageData)]));}
function changeExportSelection(){const c=current();pdfExportSelection.set(c.id,[...document.querySelectorAll('.exportcheck:checked')].map(e=>e.value));pdfExportAttempt='';render();}
function queueExportPreparation(){if(route!=='export'||pdfBusy)return;const key=exportSelectionKey();if(!selectedExportIds().length||pdfExportAttempt===key)return;clearTimeout(pdfExportTimer);pdfExportTimer=setTimeout(()=>{if(route==='export'&&!pdfBusy&&exportSelectionKey()===key)doExport();},100);}
function exportDownloadAction(){const p=pdfPreparedDownload,key=exportSelectionKey();const icon='<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/></svg> ';
 if(p&&p.caseId===current().id&&p.selectionKey===key)return `<a id="exportSelected" class="primary native-export-link" href="${esc(p.url)}" download="${esc(p.name)}" onclick="return pdfDownloadRequested(this)">${icon}匯出檔案</a>`;
 const retry=!pdfBusy&&pdfExportAttempt===key&&selectedExportIds().length;return `<button id="exportSelected" class="primary" ${retry?'':'disabled'} onclick="pdfExportAttempt='';doExport()">${icon}${pdfBusy?'準備 ZIP 中…':retry?'重新準備檔案':'匯出檔案'}</button>`;
}
function exportNotes(){return `<details class="card export-notes"><summary>備註與匯出規格</summary><ul><li>每頁依實際內容輸出：未遮蔽頁保留原始向量與尺寸；有遮蔽頁白色不可逆遮蔽並以 600 dpi 無損影像輸出；備註是可在 Adobe Acrobat 編輯的便利貼註解。約 100 KB／PDF 是目標，不會降低畫質以符合容量；超過時下載前提示。</li><li>600 dpi、無損壓縮，保留原始紙張尺寸、頁數及順序。列印請選「實際大小／100%」。</li><li>單頁上限 8,000 萬像素；超出會提示失敗，不會自動降低解析度。</li><li>下載 ZIP 包含成功的 PDF 與匯出清單；失敗項目請修正後重試。</li><li>系統先準備 ZIP；完成後按「匯出檔案」下載。若內嵌頁面限制下載，請在獨立分頁開啟本站後重試。下載要求不代表檔案已儲存至裝置。</li></ul></details>`;}
function exportProgressCard(){const s=pdfExportState;if(!s||s.caseId!==current()?.id)return '';return `<div class="export-progress" aria-live="polite"><p>${esc(s.text)}</p>${s.running?`<progress value="${s.value}" max="100" aria-label="匯出進度"></progress><button onclick="cancelInlineExport()">取消匯出</button>`:''}${s.results.filter(r=>r.result==='失敗').map(r=>`<p class="review-important">${esc(r.file)}：${esc(r.reason)}</p>`).join('')}</div>`;}
function updateInlineExport(text,value){if(!pdfExportState)return;pdfExportState.text=text;pdfExportState.value=value;const el=document.querySelector('#exportProgress');if(el)el.innerHTML=exportProgressCard();}
function cancelInlineExport(){const s=pdfExportState;if(!s?.running)return;s.cancelRequested=true;s.controller.abort();updateInlineExport('正在取消匯出…',s.value);}
exportPage=function(){const c=current(),groups=pdfGroups(c),ready=groups.filter(g=>g.pages.every(isExportReady));return title('成果與匯出',esc(c.name),btn('返回案件主頁',"go('case')"))+exportSummary(c)+`<div class="export-sections"><section class="card"><div class="cardhead"><h2>可匯出檔案</h2>${exportDownloadAction()}</div>${ready.map(g=>`<label class="checkrow"><input class="exportcheck" type="checkbox" value="${esc(g.id)}" ${selectedExportIds(c).includes(g.id)?'checked':''} ${!g.real||pdfBusy?'disabled':''} onchange="changeExportSelection()"><b>${esc(g.name)}</b><span class="pill">${g.pages.length} 頁</span>${g.real?'':badge('示範 · 無原始 PDF')}</label>`).join('')||'<p class="empty">尚無整份通過的 PDF。</p>'}<div id="exportProgress">${exportProgressCard()}</div>${pdfDownloadCard()}</section><section class="card"><h2>匯出紀錄</h2>${logs.filter(l=>l.caseId===cid&&l.action.startsWith('PDF 匯出')).map(l=>`<p>${esc(l.time)} · ${esc(l.file)} · ${esc(l.action)}</p>`).join('')||'<p>尚無 PDF 匯出紀錄</p>'}</section>${exportNotes()}</div>`;};
function pdfZipName(c,now=new Date()){
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
 const date=['year','month','day'].map(type=>parts.find(p=>p.type===type).value).join('');
 const name=String(c.name||'案件').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').replace(/[. ]+$/g,'').trim()||'案件';
 return name+'_NL_'+date+'.zip';
}
let pdfPreparedDownload=null;
function pdfDownload(blob,name,caseId,groups){
 if(!blob||!blob.size)throw Error('產生的下載檔案是空的，請重新匯出。');
 if(pdfPreparedDownload)URL.revokeObjectURL(pdfPreparedDownload.url);
 pdfPreparedDownload={url:URL.createObjectURL(blob),name,size:blob.size,caseId,requested:false,
  files:groups.map(g=>({name:g.name,pages:g.pages.map(f=>({id:f.id,sourceId:f.sourceId,pageIndex:f.pageIndex,key:pdfKey(f)}))}))};
}
function pdfDownloadCard(){const p=pdfPreparedDownload;if(!p||p.caseId!==current()?.id||p.selectionKey!==exportSelectionKey())return '';return `<div class="pdf-download-ready" role="status"><span>${esc(p.name)} · ${pdfUploadSize(p.size)}</span> <a class="pdf-download-link" href="${esc(p.url)}" download="${esc(p.name)}" onclick="return pdfDownloadRequested(this)">重新下載 ZIP</a><p class="pdf-download-status">${p.requested?'已發出下載要求，請查看瀏覽器下載清單。':'檔案已準備好，可點擊連結下載。'}</p></div>`;}

function pdfDownloadRequested(link){const p=pdfPreparedDownload;if(!p||p.caseId!==current()?.id||p.selectionKey!==exportSelectionKey())return false;
 const oversized=p.pdfSizes?.filter(f=>f.bytes>102400)||[];
 if(oversized.length&&!confirm('以下 PDF 超過約 100 KB 目標（不降低畫質）：\n'+oversized.map(f=>`${f.name}：${pdfUploadSize(f.bytes)}`).join('\n')+'\n仍要下載嗎？'))return false;
 p.name=pdfZipName(current());if(link)link.download=p.name;
 if(!p.requested){p.requested=true;const c=cases.find(c=>c.id===p.caseId);
  if(c){for(const g of p.files){for(const saved of g.pages){const f=c.files.find(f=>f.id===saved.id&&f.sourceId===saved.sourceId&&f.pageIndex===saved.pageIndex);if(f&&pdfKey(f)===saved.key&&isExportReady(f))f.status='已匯出';}
   logs.push({caseId:c.id,file:g.name,time:new Date().toLocaleString('zh-TW'),action:`PDF 匯出 · 已發出下載要求 · ${g.pages.length} 頁`});}writeCaseStore();}
 }
 document.querySelectorAll('.pdf-download-status').forEach(el=>el.textContent='已發出下載要求；請查看瀏覽器下載清單。若未收到，可再次點擊下載。');
 // Let the native link's default action complete before updating the underlying page.
 setTimeout(()=>{if(route==='export')render();},1000);
 return true;
}
window.addEventListener('pagehide',e=>{if(!e.persisted&&pdfPreparedDownload)URL.revokeObjectURL(pdfPreparedDownload.url);});
doExport=async function(){
 if(pdfBusy)return;
 const c=current(),ids=selectedExportIds(c),groups=pdfGroups(c).filter(g=>g.real&&ids.includes(g.id)&&g.pages.every(isExportReady));
 if(!groups.length)return notify('請選擇已通過的真實 PDF');
 const selectionKey=exportSelectionKey(c);pdfExportAttempt=selectionKey;
 if(pdfPreparedDownload){URL.revokeObjectURL(pdfPreparedDownload.url);pdfPreparedDownload=null;}
 const d=pdfExportState={caseId:c.id,text:'準備匯出…',value:0,running:true,cancelRequested:false,controller:new AbortController(),results:[]};
 pdfBusy=true;pdfActiveTask=d;const zip=new JSZip(),success=[];render();
 try{
  for(let i=0;i<groups.length;i++){
   if(d.cancelRequested)break;const g=groups[i];updateInlineExport(`處理 ${i+1} / ${groups.length}：${g.name}`,i/groups.length*90);
   try{const output=await finalDocument(g,d.controller.signal);if(d.cancelRequested)break;const name=g.name.replace(/\.pdf$/i,'')+'_NL.pdf',outputPath=zip.file(name)?'同名檔案_'+(i+1)+'/'+name:name;zip.file(outputPath,output);success.push(g);d.results.push({file:g.name,pages:g.pages.length,result:'成功',output:outputPath,bytes:output.byteLength});}
   catch(e){if(d.cancelRequested)break;d.results.push({file:g.name,pages:g.pages.length,result:'失敗',reason:e.message});}
  }
  if(d.cancelRequested){d.text='已取消匯出，未發出下載要求。';return;}
  if(success.length){zip.file('匯出清單.json',JSON.stringify({case:c.name,time:new Date().toISOString(),format:'未遮蔽頁保留向量；遮蔽頁白色不可逆點陣化；備註為可編輯 PDF 註解',dpi:600,compression:'lossless',files:d.results},null,2));updateInlineExport('打包下載檔案…',95);const zipBytes=await zip.generateAsync({type:'uint8array',compression:'STORE'});const verified=await JSZip.loadAsync(zipBytes,{checkCRC32:true});if(verified.file(/\.pdf$/i).length!==success.length)throw Error('ZIP 內容驗證失敗，請重新準備檔案。');const blob=new Blob([zipBytes],{type:'application/zip'});if(d.cancelRequested){d.text='已取消匯出，未發出下載要求。';return;}pdfDownload(blob,pdfZipName(c),c.id,success);pdfPreparedDownload.selectionKey=selectionKey;pdfPreparedDownload.pdfSizes=d.results.filter(r=>r.result==='成功').map(r=>({name:r.output,bytes:r.bytes}));d.text=`已準備 ${success.length} / ${groups.length} 份：${pdfPreparedDownload.pdfSizes.map(f=>`${f.name} ${pdfUploadSize(f.bytes)}`).join('；')}。請按「匯出檔案」下載 ZIP。`;}
  else d.text='沒有成功產生檔案，請查看原因後重試。';d.value=100;
 }catch(e){d.text=d.cancelRequested?'已取消匯出，未發出下載要求。':'匯出未完成：'+e.message;}
 finally{d.running=false;d.finished=true;if(pdfActiveTask===d){pdfBusy=false;pdfActiveTask=null;}if(route==='export')render();}
};
async function pdfMountPreview(){const f=file();if(!f?.sourceId||!['work','review'].includes(route))return;const canvas=document.querySelector('.pdf-canvas');if(!canvas)return;const token=++pdfPreviewToken,processed=route==='review',key=pdfKey(f),width=Math.max(1400,Math.min(3500,Math.round(canvas.parentElement.clientWidth*(devicePixelRatio||1)))),cacheKey=(processed?key:f.sourceId+':'+f.pageIndex+':'+(f.rotation||0))+':'+width;const message=canvas.parentElement.querySelector('.pdf-render-message');try{let result=pdfImages.get(cacheKey);if(!result){result=await pdfCall('render',{bytes:await pdfBytes(f),pageIndex:f.pageIndex,width,page:processed?pdfPageData(f):{rotation:f.rotation||0,masks:[],notes:[]}});pdfImages.set(cacheKey,result);while(pdfImages.size>6)pdfImages.delete(pdfImages.keys().next().value);}if(token!==pdfPreviewToken||!canvas.isConnected)return;const bitmap=await createImageBitmap(new Blob([result.png],{type:'image/png'}));if(token!==pdfPreviewToken||!canvas.isConnected){bitmap.close();return;}canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d').drawImage(bitmap,0,0);bitmap.close();message?.remove();if(processed){pdfPreviewReady=key;syncReviewApproval();}else pdfWorkReady=f.sourceId+':'+f.pageIndex;}catch(e){if(token!==pdfPreviewToken)return;if(message){message.textContent=e.message;message.classList.add('pdf-render-error');}if(processed)pdfPreviewReady='';}}
const originalZoom=setZoom;setZoom=function(n){originalZoom(n);if(file()?.sourceId){clearTimeout(window.pdfZoomTimer);window.pdfZoomTimer=setTimeout(pdfMountPreview,180);}};
const originalRender=render;render=function(){pdfPreviewToken++;originalRender();if(['work','review'].includes(route)&&file()?.sourceId)pdfMountPreview();};
// Remove source blobs only after the existing confirmation and metadata commit succeed.
const originalDelete=confirmCaseDeletion;confirmCaseDeletion=function(){const ids=[...pendingDeleteCaseIds],sources=cases.filter(c=>ids.includes(c.id)).flatMap(c=>pdfGroups(c).filter(g=>g.real).map(g=>g.id));originalDelete();if(!cases.some(c=>ids.includes(c.id)))for(const id of sources)pdfStore('delete',id).catch(()=>{});};
// Keep page units explicit after introducing multi-page documents.
const originalCaseRows=caseRows;caseRows=function(){const rows=visibleCaseRows();let i=0;return originalCaseRows().replace(/<td>(\d+) 份<\/td>/g,()=>{const c=rows[i++];return `<td>${pdfGroups(c).length} 份 / ${c.files.length} 頁</td>`;});};
const originalDashboard=dashboard;dashboard=function(){return originalDashboard().replaceAll('總圖面數','總頁數').replaceAll('份圖面','頁圖面').replaceAll('單位為圖面份數','單位為圖面頁數').replaceAll('含所有圖面','含所有頁面');};

// One confirmation per page, in the workbench. Preview is read-only.
isExportReady=function(f){return f.status!=='處理失敗'&&(f.accepted===true||['可匯出','已匯出'].includes(f.status));};
acceptMask=function(){const f=file();if(!f||f.status==='處理失敗')return;if(f.sourceId&&pdfWorkReady!==f.sourceId+':'+f.pageIndex)return notify('請等待圖面載入完成後再確認');f.accepted=true;f.status='可匯出';f.approvedRevision=f.revision||0;markCaseUnsaved();render();notify('本頁已確認；同一份 PDF 全部頁面確認後即可匯出。');};
reviewStatus=function(f){return f.status==='處理失敗'?'處理失敗':isExportReady(f)?(f.status==='已匯出'?'已匯出':'可匯出'):'待工作台確認';};
syncReviewApproval=function(){};
const singleConfirmBar=drawingConfirmation;drawingConfirmation=function(f){return singleConfirmBar(f).replace('請核對遮蔽範圍、備註色塊與必要技術資訊，完成後再標記確認。','確認前請逐一核對敏感資訊遮蔽、備註內容與位置，並保留尺寸、公差及必要技術資訊。標記後視為本頁核對完成，預覽頁不再重複確認。').replace('可繼續核對其他圖面，或前往「預覽與確認」。再次修改內容後需重新確認。','本頁已完成核對；整份 PDF 全部頁面確認後即可匯出。請於預覽頁檢視最終出圖，再次修改後需重新確認。');};
let reviewFiltersOpen=false;
function toggleReviewFilters(){reviewFiltersOpen=!reviewFiltersOpen;const panel=$('#reviewFilters'),button=$('#reviewFilterToggle');if(panel)panel.hidden=!reviewFiltersOpen;if(button)button.setAttribute('aria-expanded',String(reviewFiltersOpen));}
reviewPage=function(){if(!current().files.length){go('case');return '';}ensureEditor();return title('預覽與人工確認','',reviewExportAction()).replace('<p></p>','')+exportSummary(current())+reviewProgress();};
reviewProgress=function(){const c=current(),f=file();if(reviewCaseId!==c.id){reviewCaseId=c.id;reviewQuery='';reviewFilter='全部';reviewListPage=reviewGroupPage(fi);reviewZoom=100;reviewFiltersOpen=false;}if(reviewFilter==='待最終核對')reviewFilter='全部';const rows=reviewMatches(),pos=rows.findIndex(r=>r.i===fi);return `<section class="review-layout"><div class="card review-browser"><div class="review-browser-heading"><h2>核對圖面</h2><button id="reviewFilterToggle" type="button" class="case-icon" aria-label="展開或收折圖面篩選" title="搜尋與篩選" aria-expanded="${reviewFiltersOpen}" aria-controls="reviewFilters" onclick="toggleReviewFilters()"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="white"/><circle cx="15" cy="12" r="2" fill="white"/><circle cx="9" cy="18" r="2" fill="white"/></svg></button></div><div id="reviewFilters" ${reviewFiltersOpen?'':'hidden'}><label class="field">搜尋檔名<input type="search" placeholder="輸入檔名搜尋" value="${esc(reviewQuery)}" oninput="reviewQuery=this.value;reviewListPage=0;refreshReviewList()"></label><label class="field">核對狀態<select onchange="reviewFilter=this.value;reviewListPage=0;refreshReviewList()">${['全部','待工作台確認','處理失敗','可匯出','已匯出'].map(t=>`<option ${t===reviewFilter?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="reviewFileResults">${reviewList()}</div></div><div class="card review-preview"><div class="cardhead"><div><h2>最終出圖預覽</h2><p class="review-current-name">${esc(pdfLabel(f))}</p></div><span>第 ${fi+1} / ${c.files.length} 頁</span></div><div class="review-navigation"><button id="reviewPrevious" onclick="reviewAdjacent(-1)" ${pos>0?'':'disabled'}>上一張</button>${btn('繼續編輯此圖面',"go('work')")}<button id="reviewNext" onclick="reviewAdjacent(1)" ${pos>=0&&pos<rows.length-1?'':'disabled'}>下一張</button></div>${reviewPreview(f)}</div></section>`;};
function reviewZoomIcon(plus){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="M15 15l6 6M7 10h6${plus?'M10 7v6':''}"/></svg>`;}
const compactReviewPreview=reviewPreview;reviewPreview=function(f){let html=compactReviewPreview(f);html=html.replace(/<button id="reviewZoomOut"[^>]*>[^<]*<\/button>/,`<button id="reviewZoomOut" aria-label="縮小預覽" title="縮小" ${reviewZoom===50?'disabled':''} onclick="setReviewZoom(reviewZoom-25)">${reviewZoomIcon(false)}</button>`).replace(/<button id="reviewZoomIn"[^>]*>[^<]*<\/button>/,`<button id="reviewZoomIn" aria-label="放大預覽" title="放大" ${reviewZoom===200?'disabled':''} onclick="setReviewZoom(reviewZoom+25)">${reviewZoomIcon(true)}</button>`);return html;};
function bindReviewPan(){const viewport=document.querySelector('.review-preview-viewport');if(!viewport)return;viewport.classList.add('review-pannable');viewport.onpointerdown=e=>{if(e.button!==0||!(viewport.scrollWidth>viewport.clientWidth||viewport.scrollHeight>viewport.clientHeight))return;e.preventDefault();const x=e.clientX,y=e.clientY,left=viewport.scrollLeft,top=viewport.scrollTop;viewport.setPointerCapture(e.pointerId);viewport.classList.add('is-panning');viewport.onpointermove=ev=>{viewport.scrollLeft=left-(ev.clientX-x);viewport.scrollTop=top-(ev.clientY-y);};const end=()=>{viewport.onpointermove=null;viewport.classList.remove('is-panning');};viewport.onpointerup=viewport.onpointercancel=viewport.onlostpointercapture=end;};}
const reviewPanRender=render;render=function(){reviewPanRender();if(route==='review')bindReviewPan();};

let workFiltersOpen=false;
function toggleWorkFilters(){workFiltersOpen=!workFiltersOpen;$('#workFilters').hidden=!workFiltersOpen;$('#workFilterToggle').setAttribute('aria-expanded',String(workFiltersOpen));}
const fullWorkControls=workListControls;workListControls=function(){return `<div class="review-browser-heading"><h3>圖面清單</h3><button type="button" id="workFilterToggle" class="case-icon" title="搜尋、篩選與排序" aria-label="搜尋、篩選與排序" aria-controls="workFilters" aria-expanded="${workFiltersOpen}" onclick="toggleWorkFilters()"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="white"/><circle cx="15" cy="12" r="2" fill="white"/><circle cx="9" cy="18" r="2" fill="white"/></svg></button></div><div id="workFilters" ${workFiltersOpen?'':'hidden'}>${fullWorkControls().replace('<h3>圖面清單</h3>','')}</div>`;};
function pageArrow(right){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${right?'m9 5 7 7-7 7':'m15 5-7 7 7 7'}"/></svg>`;}
const fullPageNavigation=pdfPageNavigation;pdfPageNavigation=function(f){return fullPageNavigation(f).replace(/<button ([^>]*)>上一頁<\/button>/,`<button title="上一頁" aria-label="上一頁" $1>${pageArrow(false)}</button>`).replace(/<button ([^>]*)>下一頁<\/button>/,`<button title="下一頁" aria-label="下一頁" $1>${pageArrow(true)}</button>`);};
workFileList=function(){const groups=pdfGroups().map(g=>({...g,total:g.pages.length,pages:g.pages.filter(f=>(workStatus==='全部'||workFileStatus(f)===workStatus)&&f.name.toLowerCase().includes(workSearch.toLowerCase()))})).filter(g=>g.pages.length);if(workSort!=='original')groups.sort((a,b)=>a.name.localeCompare(b.name,'zh-TW',{numeric:true})*(workSort==='desc'?-1:1));const pages=Math.max(1,Math.ceil(groups.length/20));pdfWorkPage=Math.min(pdfWorkPage,pages-1);return `<p class="file-result-count">${groups.length} 份檔案 · ${groups.reduce((n,g)=>n+g.pages.length,0)} 頁符合</p>`+groups.slice(pdfWorkPage*20,pdfWorkPage*20+20).map(g=>g.total===1?`<button class="work-single-file review-file ${g.pages[0]===file()?'active selected':''}" aria-current="${g.pages[0]===file()}" onclick="pdfSelectPage(${current().files.indexOf(g.pages[0])})"><strong>${esc(g.name)}</strong>${badge(workFileStatus(g.pages[0]))}</button>`:`<details class="pdf-file-group" ${g.pages.includes(file())?'open':''}><summary><strong>${esc(g.name)}</strong><small>${g.total} 頁 · 已確認 ${pdfGroups().find(x=>x.id===g.id).pages.filter(isExportReady).length} 頁</small></summary>${g.pages.map(f=>`<button class="${f===file()?'selected':''}" onclick="pdfSelectPage(${current().files.indexOf(f)})"><span>第 ${(f.pageIndex||0)+1} 頁</span>${badge(workFileStatus(f))}</button>`).join('')}</details>`).join('')+`<div class="pdf-list-pager"><button title="上一頁檔案清單" aria-label="上一頁檔案清單" ${pdfWorkPage?'':'disabled'} onclick="pdfWorkPage--;refreshWorkFiles()">${pageArrow(false)}</button><small>${pdfWorkPage+1} / ${pages}</small><button title="下一頁檔案清單" aria-label="下一頁檔案清單" ${pdfWorkPage+1<pages?'':'disabled'} onclick="pdfWorkPage++;refreshWorkFiles()">${pageArrow(true)}</button></div>`;};
const compactWorkbench=workPage;workPage=function(){let html=compactWorkbench();if(!current().files.length)return html;html=html.replace(/(<div class="page-title-row">[\s\S]*?<\/h1><\/div>)<p>[\s\S]*?<\/p>/,'$1').replace(/<button[^>]*onclick="addMask\(\)"[^>]*>[\s\S]*?<\/button>/,'');if(!file().sourceId)html=html.replace('<div class="canvasbar">',`<div class="canvasbar"><button class="${pdfDrawMode?'primary':''}" aria-pressed="${pdfDrawMode}" onclick="pdfDrawMode=!pdfDrawMode;view='處理預覽';render()">${uiIcon('mask')}圈選遮蔽</button>`);const help='100% 為適合視窗；可在圖面區以觸控板雙指捏合縮放，放大後拖曳空白處平移。選取物件後可拖曳移動，使用控制點縮放。備註選取後點文字可直接編輯；拖曳編號移動便利貼，Esc 結束編輯。完成後請儲存進度；修改後需重新確認。原始圖面保留，請在預覽頁檢查最終出圖。';html=html.replace('<div class="canvasbar">',`<div class="canvasbar"><span class="work-help"><button type="button" class="case-icon" aria-label="圖面操作說明" aria-describedby="workHelpText" onclick="this.parentElement.classList.toggle('is-open')"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/></svg></button><span id="workHelpText" role="tooltip">${help}</span></span>`);html=html.replace(/<p class="pan-hint">[\s\S]*?<\/p><p style="margin-top:10px">[\s\S]*?<\/p><p>[\s\S]*?<\/p>/,'');return html;};
lastColors.mask=['#000000','#FFFFFF'].includes(lastColors.mask)?lastColors.mask:'#000000';
lastColors.note=['#FFF1AE','#FFDAD6','#CDEEFF','#D8F0DB','#E8DDF5'].includes(lastColors.note)?lastColors.note:'#FFF1AE';

// Desktop workbench sizing and local trackpad zoom.
const orderedWorkbench=workPage;workPage=function(){let html=orderedWorkbench();const mask=html.match(/<button[^>]*onclick="pdfDrawMode=[^"]*"[^>]*>[\s\S]*?圈選遮蔽<\/button>/);if(mask){html=html.replace(mask[0],'');html=html.replace(/(<button[^>]*onclick="addNote\(\)"[^>]*>)/,mask[0]+'$1');}return html;};
function fitWorkbenchHeight(){const workspace=document.querySelector('#app .workspace');if(!workspace)return;if(window.innerWidth>1100){const top=workspace.getBoundingClientRect().top+window.scrollY;workspace.style.setProperty('--work-height',Math.max(320,window.innerHeight-top-20)+'px');}else workspace.style.removeProperty('--work-height');sizeDrawing();}
function zoomDrawingAt(value,clientX,clientY){const viewport=$('#drawingViewport'),paper=$('#paper');if(!viewport||!paper)return;const before=paper.getBoundingClientRect(),u=(clientX-before.left)/before.width,v=(clientY-before.top)/before.height;setZoom(Math.round(Math.max(50,Math.min(200,value))));const after=paper.getBoundingClientRect();viewport.scrollLeft+=after.left+u*after.width-clientX;viewport.scrollTop+=after.top+v*after.height-clientY;}
function bindTrackpadZoom(){const viewport=$('#drawingViewport');if(!viewport)return;viewport.addEventListener('wheel',event=>{if(!event.ctrlKey)return;event.preventDefault();const delta=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?viewport.clientHeight:1);zoomDrawingAt(zoomLevel*Math.exp(-delta*.01),event.clientX,event.clientY);},{passive:false});let gestureStart=100;viewport.addEventListener('gesturestart',event=>{event.preventDefault();gestureStart=zoomLevel;},{passive:false});viewport.addEventListener('gesturechange',event=>{event.preventDefault();const b=viewport.getBoundingClientRect();zoomDrawingAt(gestureStart*event.scale,event.clientX||b.left+b.width/2,event.clientY||b.top+b.height/2);},{passive:false});viewport.addEventListener('gestureend',event=>event.preventDefault(),{passive:false});}
const fittedWorkbenchRender=render;render=function(){fittedWorkbenchRender();if(route==='work'){fitWorkbenchHeight();bindTrackpadZoom();}};
window.addEventListener('resize',fitWorkbenchHeight);

render();

